//! 🏛️ Admitted Model spatial placements, complete classes, typed properties and relations.
use semio_s_artifact_stdio_semio_base::schema::geometry::SemioTransform;
use semio_s_artifact_stdio_semio_base::schema::geometry::SemioPoint3;
use semio_s_artifact_stdio_semio_base::schema::geometry::SemioQuaternion;
use crate::schema::snapshot::{SemioModelSnapshot, SpatialKind, ElementClass, GeometryRef, PropertySet, Property, PsetValue, RelationKind, STDIO_SEMIOMODEL_DOCUMENT_SCHEMA};
use semio_s_artifact_stdio_semio_base::io::sqlite::snapshot::native_decoding::{self as native,workspace};
use semio_framework_value_native_owned::native_decoding::NativeDecodeControl;
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
/// 🛬️ Separates complete SQL cells from the same caller's actual native allocation backing.
pub(crate)fn decode(payload:&store::io::IoPayload,control:&mut SqliteSnapshotControl<'_>,native_control:&mut NativeDecodeControl<'_>)->Result<SemioModelSnapshot,ValueError>{
 crate::io::sqlite::snapshot::admit_layout(control.limits())?;
 native::with_body(payload,STDIO_SEMIOMODEL_DOCUMENT_SCHEMA,control,native_control,|body,decoder,limits|workspace::decode(decoder,empty,|output,decoder|match body{native::Body::Binary(body)=>binary_into(output,body,decoder,limits),native::Body::Text(body)=>document_into(output,body,decoder,limits)}))
}
fn f64(reader:&mut store::ByteReader<'_>)->Result<f64,ValueError>{reader.read_f64_le().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))}
fn point(reader:&mut store::ByteReader<'_>)->Result<SemioPoint3,ValueError>{Ok(SemioPoint3{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?})}
fn transform(reader:&mut store::ByteReader<'_>)->Result<SemioTransform,ValueError>{Ok(SemioTransform{translation:point(reader)?,rotation:SemioQuaternion{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?,w:f64(reader)?},scale:point(reader)?})}





/// 🧾️ Creates a zero-heap property whose key and value are filled in place.
fn empty_property()->Property{Property{key:String::new(),value:PsetValue::Boolean{value:false}}}
/// 🗃️ Creates a zero-heap property set whose name and properties are filled in place.
fn empty_pset()->PropertySet{PropertySet{name:String::new(),properties:Vec::new()}}
/// 🔘️ Fills one optional identifier in its original slot from borrowed binary octets.
fn option_into(output:&mut Option<String>,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>Ok(()),1=>{*output=Some(String::new());native::reader_text_into(output.as_mut().unwrap(),reader,control)},_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native optional presence"))}}
/// 🏷️ Selects each binary element class in its retained slot before copying a custom name.
fn class_binary_into(output:&mut ElementClass,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>*output=ElementClass::Wall,1=>*output=ElementClass::Slab,2=>*output=ElementClass::Column,3=>*output=ElementClass::Beam,4=>*output=ElementClass::Door,5=>*output=ElementClass::Window,6=>*output=ElementClass::Roof,7=>*output=ElementClass::Stair,8=>*output=ElementClass::Furniture,9=>{*output=ElementClass::Other{name:String::new()};let ElementClass::Other{name}=&mut *output else{unreachable!()};native::reader_text_into(name,reader,control)?;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native element class"))}Ok(())}
/// 📍️ Selects each binary geometry reference in its retained slot before copying its identifier.
fn geometry_binary_into(output:&mut GeometryRef,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>*output=GeometryRef::None,1=>{*output=GeometryRef::Brep{brep_id:String::new()};let GeometryRef::Brep{brep_id}=&mut *output else{unreachable!()};native::reader_text_into(brep_id,reader,control)?;},2=>{*output=GeometryRef::Mesh{mesh_id:String::new()};let GeometryRef::Mesh{mesh_id}=&mut *output else{unreachable!()};native::reader_text_into(mesh_id,reader,control)?;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native geometry reference"))}Ok(())}
/// 💠️ Selects each binary property value in its retained slot before copying its text.
fn value_binary_into(output:&mut PsetValue,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>{*output=PsetValue::Text{value:String::new()};let PsetValue::Text{value}=&mut *output else{unreachable!()};native::reader_text_into(value,reader,control)?;},1=>*output=PsetValue::Number{value:f64(reader)?},2=>*output=PsetValue::Boolean{value:match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>false,1=>true,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native property boolean"))}},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native property kind"))}Ok(())}
/// 🤝️ Selects each binary relation kind in its retained slot before copying a custom label.
fn relation_binary_into(output:&mut RelationKind,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>*output=RelationKind::Aggregates,1=>*output=RelationKind::ContainedIn,2=>*output=RelationKind::ConnectsTo,3=>*output=RelationKind::FillsVoid,4=>*output=RelationKind::VoidsElement,5=>{*output=RelationKind::Other{label:String::new()};let RelationKind::Other{label}=&mut *output else{unreachable!()};native::reader_text_into(label,reader,control)?;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native relation kind"))}Ok(())}
/// 🧩️ Fills the retained model root from borrowed binary octets, inserting every node, element, property and relation before its fields.
pub fn binary_into(output:&mut SemioModelSnapshot,body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<(),ValueError>{crate::io::sqlite::snapshot::admit_binary(body,control,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unsupported Model native format"))}let mut entities=0;native::entities(&mut entities,1,limits)?;native::reader_text_into(&mut output.schema,&mut reader,control)?;
 native::binary_list_into(&mut output.spatial,&mut reader,control,limits,&mut entities,Default::default,|node,reader,control,entities|{native::entities(entities,2,limits)?;native::reader_text_into(&mut node.id,reader,control)?;node.kind=match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>SpatialKind::Site,1=>SpatialKind::Building,2=>SpatialKind::Storey,3=>SpatialKind::Space,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native spatial kind"))};native::reader_text_into(&mut node.name,reader,control)?;option_into(&mut node.parent_id,reader,control)?;node.placement=transform(reader)?;Ok(())})?;
 native::binary_list_into(&mut output.elements,&mut reader,control,limits,&mut entities,Default::default,|element,reader,control,entities|{native::entities(entities,3,limits)?;native::reader_text_into(&mut element.id,reader,control)?;class_binary_into(&mut element.class,reader,control)?;element.placement=transform(reader)?;geometry_binary_into(&mut element.geometry,reader,control)?;option_into(&mut element.spatial_id,reader,control)?;
  native::binary_list_into(&mut element.psets,reader,control,limits,entities,empty_pset,|pset,reader,control,entities|{native::reader_text_into(&mut pset.name,reader,control)?;native::binary_list_into(&mut pset.properties,reader,control,limits,entities,empty_property,|property,reader,control,_|{native::reader_text_into(&mut property.key,reader,control)?;value_binary_into(&mut property.value,reader,control)})})
 })?;
 native::binary_list_into(&mut output.relations,&mut reader,control,limits,&mut entities,Default::default,|relation,reader,control,_|{native::reader_text_into(&mut relation.id,reader,control)?;relation_binary_into(&mut relation.kind,reader,control)?;native::reader_text_into(&mut relation.from,reader,control)?;native::reader_text_into(&mut relation.to,reader,control)})?;if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Model native trailing bytes"))}Ok(())}

fn point_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioPoint3,ValueError>{let[x,y,z]=native::record(value,control)?;Ok(SemioPoint3{x:native::float(x,control)?,y:native::float(y,control)?,z:native::float(z,control)?})}
fn transform_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioTransform,ValueError>{let[translation,rotation,scale]=native::record(value,control)?;let[x,y,z,w]=native::record(rotation,control)?;Ok(SemioTransform{translation:point_text(translation,control)?,rotation:SemioQuaternion{x:native::float(x,control)?,y:native::float(y,control)?,z:native::float(z,control)?,w:native::float(w,control)?},scale:point_text(scale,control)?})}




/// ☑️ Fills one optional identifier in its original slot from a bracketed hexadecimal record.
fn option_text_into(output:&mut Option<String>,value:&str,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{if value=="[0]"{return Ok(())}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native optional presence"))}*output=Some(String::new());native::hex_text_into(output.as_mut().unwrap(),value,control)}
/// 🔖️ Selects each text element class in its retained slot before copying a custom name.
fn class_text_into(output:&mut ElementClass,value:&str,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{match value{"WA"=>*output=ElementClass::Wall,"SL"=>*output=ElementClass::Slab,"CO"=>*output=ElementClass::Column,"BE"=>*output=ElementClass::Beam,"DO"=>*output=ElementClass::Door,"WI"=>*output=ElementClass::Window,"RO"=>*output=ElementClass::Roof,"ST"=>*output=ElementClass::Stair,"FU"=>*output=ElementClass::Furniture,_=>{let value=value.strip_prefix("OT").ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native class"))?;let[name]=native::record(value,control)?;*output=ElementClass::Other{name:String::new()};let ElementClass::Other{name:slot}=&mut *output else{unreachable!()};native::hex_text_into(slot,name,control)?;}}Ok(())}
/// 🗺️ Selects each text geometry reference in its retained slot before copying its identifier.
fn geometry_text_into(output:&mut GeometryRef,value:&str,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{if value=="N"{*output=GeometryRef::None;return Ok(())}let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Model geometry tag missing"))?;let[id]=native::record(value,control)?;match tag{"B"=>{*output=GeometryRef::Brep{brep_id:String::new()};let GeometryRef::Brep{brep_id}=&mut *output else{unreachable!()};native::hex_text_into(brep_id,id,control)?;},"M"=>{*output=GeometryRef::Mesh{mesh_id:String::new()};let GeometryRef::Mesh{mesh_id}=&mut *output else{unreachable!()};native::hex_text_into(mesh_id,id,control)?;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native geometry kind"))}Ok(())}
/// 🔷️ Selects each text property value in its retained slot before copying its text.
fn value_text_into(output:&mut PsetValue,value:&str,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Model property tag missing"))?;let[value]=native::record(value,control)?;match tag{"T"=>{*output=PsetValue::Text{value:String::new()};let PsetValue::Text{value:slot}=&mut *output else{unreachable!()};native::hex_text_into(slot,value,control)?;},"N"=>*output=PsetValue::Number{value:native::float(value,control)?},"B"=>*output=PsetValue::Boolean{value:match value{"0"=>false,"1"=>true,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native property boolean"))}},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native property kind"))}Ok(())}
/// 🔁️ Selects each text relation kind in its retained slot before copying a custom label.
fn relation_text_into(output:&mut RelationKind,value:&str,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{match value{"AG"=>*output=RelationKind::Aggregates,"CI"=>*output=RelationKind::ContainedIn,"CN"=>*output=RelationKind::ConnectsTo,"FV"=>*output=RelationKind::FillsVoid,"VE"=>*output=RelationKind::VoidsElement,_=>{let value=value.strip_prefix("OT").ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native relation kind"))?;let[label]=native::record(value,control)?;*output=RelationKind::Other{label:String::new()};let RelationKind::Other{label:slot}=&mut *output else{unreachable!()};native::hex_text_into(slot,label,control)?;}}Ok(())}
/// 📝️ Fills the retained model root from the borrowed document body, inserting every node, element, property and relation before its fields.
pub fn document_into(output:&mut SemioModelSnapshot,body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<(),ValueError>{crate::io::sqlite::snapshot::admit_document(body,control,limits)?;let fields=native::fields(body,["schema","spatial","elements","relations"],control)?;let mut entities=0;native::entities(&mut entities,1,limits)?;native::hex_text_into(&mut output.schema,fields[0].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Model native schema missing"))?,control)?;
 native::text_list_into(&mut output.spatial,fields[1].unwrap_or("[]"),control,limits,&mut entities,Default::default,|node,value,control,entities|{native::entities(entities,2,limits)?;let[id,kind,name,parent_id,placement]=native::record(value,control)?;node.kind=match kind{"S"=>SpatialKind::Site,"B"=>SpatialKind::Building,"T"=>SpatialKind::Storey,"P"=>SpatialKind::Space,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Model native spatial kind"))};native::hex_text_into(&mut node.id,id,control)?;native::hex_text_into(&mut node.name,name,control)?;option_text_into(&mut node.parent_id,parent_id,control)?;node.placement=transform_text(placement,control)?;Ok(())})?;
 native::text_list_into(&mut output.elements,fields[2].unwrap_or("[]"),control,limits,&mut entities,Default::default,|element,value,control,entities|{native::entities(entities,3,limits)?;let[id,class,placement,geometry,spatial_id,psets]=native::record(value,control)?;native::hex_text_into(&mut element.id,id,control)?;class_text_into(&mut element.class,class,control)?;element.placement=transform_text(placement,control)?;geometry_text_into(&mut element.geometry,geometry,control)?;option_text_into(&mut element.spatial_id,spatial_id,control)?;
  native::text_list_into(&mut element.psets,psets,control,limits,entities,empty_pset,|pset,value,control,entities|{let[name,properties]=native::record(value,control)?;native::hex_text_into(&mut pset.name,name,control)?;native::text_list_into(&mut pset.properties,properties,control,limits,entities,empty_property,|property,value,control,_|{let[key,value]=native::record(value,control)?;native::hex_text_into(&mut property.key,key,control)?;value_text_into(&mut property.value,value,control)})})
 })?;
 native::text_list_into(&mut output.relations,fields[3].unwrap_or("[]"),control,limits,&mut entities,Default::default,|relation,value,control,_|{let[id,kind,from,to]=native::record(value,control)?;native::hex_text_into(&mut relation.id,id,control)?;relation_text_into(&mut relation.kind,kind,control)?;native::hex_text_into(&mut relation.from,from,control)?;native::hex_text_into(&mut relation.to,to,control)})
}
/// 🕳️ The empty typed root every native prefix starts from.
pub fn empty()->SemioModelSnapshot{SemioModelSnapshot{schema:String::new(),spatial:Vec::new(),elements:Vec::new(),relations:Vec::new()}}
